VALUES ('499ca5ee-e9bb-54da-b090-76e3d8dcf92a'::uuid, '35936ba7-85b1-53ed-99b4-96a53a1f8078'::uuid, 3, 'Junior Work Review and Coaching', 'Learner uses the exact Drive-supplied artifacts CAP-CREDIT-001_L5_M03_EXPRESS_Junior_Work_Review_and_Coaching_Log_OWNER_REVIEWED_CONTROLLED_RELEASE.xlsx (EXPRESS) and CAP-CREDIT-001_L5_M03_EVOLVE_Step-Up_Coaching_and_Rework_Log_OWNER_REVIEWED_CONTROLLED_RELEASE.xlsx (EVOLVE), while preserving the L5 credit-support authority boundary.', '["Ageing queue", "Recurring defects", "Junior handoff quality", "SLA pressure", "Improvement requests", "Governance boundary"]'::jsonb, '["May call queue controlled", "May approve policy/control changes", "May issue audit-like conclusions", "May replace authorised owner decisions"]'::jsonb, 'Queue-level quality requires recurring-defect analysis, coaching and controlled improvement proposals without taking policy, audit, control or credit authority.', '["Completed L5 Module 2"]'::jsonb, '["How to complete Junior Work Review and Coaching Log using traceable evidence", "How to apply L5 status/quality logic", "How to identify the correct owner or uncertainty", "How to preserve the support-only authority boundary"]'::jsonb, 'Use during junior work review and coaching when credit-support evidence must be made traceable for the next authorised workflow owner.', '{"major_concepts": "evidence traceability, source/status logic, owner routing, L5 authority boundary, artifact quality", "implementation_context_when_to_use": "Junior Work Review and Coaching", "reason_behind_concept": "reviewer support must remain evidence-led and auditable without taking credit-decision authority"}'::jsonb, '{"ai_support_tips": "Draft first, after the first attempt, use support only for questions, evidence prompts and wording checks. Do not use AI to invent evidence, owners, status or final decisions.", "module_continuity_link": "Junior Work Review and Coaching Log becomes the carry-forward proof for the next module."}'::jsonb, '{"technical_concepts_learnt": "evidence ID, visible fact, status/defect label, owner route, unresolved item, safe support wording", "academic_refresher_concepts": "documentation quality, evidence-based reasoning, escalation, maker-checker separation, operational controls"}'::jsonb, 'The learner must turn the supplied case evidence into a reviewer-usable Junior Work Review and Coaching Log while keeping unresolved evidence visible and staying inside the L5 support boundary.', '{"items": ["Google Slides module deck", "learner artifact workbook", "evidence pack / job aid"]}'::jsonb, TRUE, TRUE)
ON CONFLICT DO NOTHING;
